package io.github.windyzhu3.ontologylaw.api;
import io.github.windyzhu3.ontologylaw.execution.CommandEnvelope;import io.github.windyzhu3.ontologylaw.identity.AuthorizationService.*;
import java.util.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.http.ResponseEntity;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;
@RestController
public class R2ContractApiDelegate {
 private final ObjectProvider<R1ApiServices> services;public R2ContractApiDelegate(ObjectProvider<R1ApiServices> services){this.services=services;}
 private R1ApiServices service(){var s=services.getIfAvailable();if(s==null)throw new R1HttpFailure("SERVICE_UNAVAILABLE");return s;}
 private Actor actor(UUID behalf){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||behalf!=null||!(a.getPrincipal() instanceof Actor actor)||actor.principalKind()!=PrincipalKind.HUMAN||actor.onBehalfAppointmentId()!=null)throw new R1HttpFailure("NOT_AUTHORIZED");return actor;}
 @GetMapping("/api/v1/opportunities/{id}/contracts") public ResponseEntity<Map<String,Object>> context(@PathVariable UUID id,@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf){return ResponseEntity.ok().header("Cache-Control","no-store").body(service().contracts(actor(behalf),id));}
 @GetMapping("/api/v1/contract-tasks/{taskId}/context") public ResponseEntity<Map<String,Object>> task(@PathVariable UUID taskId,@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf){return ResponseEntity.ok().header("Cache-Control","no-store").body(service().contractTask(actor(behalf),taskId));}
 @GetMapping("/api/v1/contracts") public ResponseEntity<Map<String,Object>> ledger(@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String cursor,@RequestParam(required=false) String search,@RequestParam(required=false) String state){return ResponseEntity.ok().header("Cache-Control","no-store").body(service().contractLedger(actor(behalf),limit,cursor,search,state));}
 @GetMapping("/api/v1/opportunities/{id}/contracts/{contractId}/versions/{versionId}/document") public ResponseEntity<byte[]> document(@PathVariable UUID id,@PathVariable UUID contractId,@PathVariable UUID versionId,@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf){return ResponseEntity.ok().header("Cache-Control","no-store").header("Content-Type","application/octet-stream").header("X-Content-Type-Options","nosniff").header("Content-Security-Policy","default-src 'none'; sandbox").header("Content-Disposition","attachment; filename=contract-"+versionId+".bin").body(service().contractDocument(actor(behalf),id,contractId,versionId));}
 @PostMapping("/api/v1/opportunities/{id}/contracts/generate") public ResponseEntity<Map<String,Object>> generate(@PathVariable UUID id,@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf,@RequestBody Map<String,Object> body){
  if(body.containsKey("opportunityId"))throw new R1HttpFailure("VALIDATION_FAILED");var p=new TreeMap<String,Object>(body);p.put("opportunityId",id.toString());var actor=actor(behalf);var envelope=new CommandEnvelope(CommandEnvelope.Type.FORM_CONTRACT,UUID.randomUUID(),UUID.randomUUID(),actor,p);
  Map<String,Object> payload;try{payload=R2ContractInput.ownerPayload(envelope);}catch(io.github.windyzhu3.ontologylaw.execution.CommandHandler.Rejected invalid){throw new R1HttpFailure(invalid.code());}
  return ResponseEntity.ok().header("Cache-Control","no-store").body(service().generateContract(actor,id,payload));
 }
 @PostMapping("/api/v1/opportunities/{id}/contracts/{action:preparation-requests|preparation-decisions|start|draft|form|review-requests|review-decisions|approval-requests|decisions|signature-draft|signature-arrangements|signature-submissions|signature-verifications|signature-archive|signature-revision|signature-verification-revision|receipt-review-requests|receipt-reviews|receipt-supplements|execution-verifications|negotiation-end|termination-review-requests|termination-review-decisions}") public ResponseEntity<Map<String,Object>> command(@PathVariable UUID id,@PathVariable String action,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader(value="X-On-Behalf-Appointment-Id",required=false) UUID behalf,@RequestBody Map<String,Object> body){var type=switch(action){case "receipt-review-requests"->CommandEnvelope.Type.REQUEST_CONTRACT_RECEIPT_REVIEW;case "receipt-reviews"->CommandEnvelope.Type.RECORD_CONTRACT_RECEIPT_REVIEW;case "receipt-supplements"->CommandEnvelope.Type.SUPPLEMENT_CONTRACT_RECEIPT;case "execution-verifications"->CommandEnvelope.Type.VERIFY_CONTRACT_EXECUTION_CONDITIONS;case "negotiation-end"->CommandEnvelope.Type.END_CONTRACT_NEGOTIATION;case "termination-review-requests"->CommandEnvelope.Type.REQUEST_CONTRACT_TERMINATION_REVIEW;case "termination-review-decisions"->CommandEnvelope.Type.RECORD_CONTRACT_TERMINATION_REVIEW;case "signature-draft"->CommandEnvelope.Type.SAVE_CONTRACT_SIGNATURE_DRAFT;case "signature-arrangements"->CommandEnvelope.Type.CONFIRM_CONTRACT_SIGNATURE_ARRANGEMENT;case "signature-submissions"->CommandEnvelope.Type.SUBMIT_CONTRACT_SIGNATURE;case "signature-verifications"->CommandEnvelope.Type.RECORD_CONTRACT_SIGNATURE_VERIFICATION;case "signature-archive"->CommandEnvelope.Type.ARCHIVE_CONTRACT_SIGNATURE;case "signature-verification-revision"->CommandEnvelope.Type.RETURN_CONTRACT_SIGNATURE_FOR_REVISION;case "signature-revision"->CommandEnvelope.Type.RETURN_CONTRACT_FOR_REVISION;case "preparation-requests"->CommandEnvelope.Type.REQUEST_CONTRACT_PREPARATION;case "preparation-decisions"->CommandEnvelope.Type.RECORD_CONTRACT_PREPARATION_DECISION;case "start"->CommandEnvelope.Type.START_CONTRACT_PREPARATION;case "draft"->CommandEnvelope.Type.SAVE_CONTRACT_DRAFT;case "form"->CommandEnvelope.Type.FORM_CONTRACT;case "review-requests"->CommandEnvelope.Type.REQUEST_CONTRACT_REVIEW;case "review-decisions"->CommandEnvelope.Type.RECORD_CONTRACT_REVIEW;case "approval-requests"->CommandEnvelope.Type.REQUEST_CONTRACT_APPROVAL;case "decisions"->CommandEnvelope.Type.RECORD_CONTRACT_DECISION;default->throw new R1HttpFailure("NOT_FOUND");};if(body.containsKey("opportunityId"))throw new R1HttpFailure("VALIDATION_FAILED");var p=new TreeMap<String,Object>(body);p.put("opportunityId",id.toString());for(String field:List.of("customerConfirmation","expectedDraft","expectedContract","expectedVersion","expectedWorkflow"))p.putIfAbsent(field,null);var envelope=new CommandEnvelope(type,key,UUID.randomUUID(),actor(behalf),p);try{R2ContractInput.parse(envelope);}catch(io.github.windyzhu3.ontologylaw.execution.CommandHandler.Rejected invalid){throw new R1HttpFailure(invalid.code());}var response=service().contractCommand(envelope);if(response.errorCode()!=null)throw new R1HttpFailure(response.errorCode(),response.receiptRef(),null,null);return ResponseEntity.status(response.status()).header("Cache-Control","no-store").header("Location","/api/v1/commands/"+key+"/receipt").body(response.body());}
}
